public boolean hasPathDownRight(int[][] maze) {
    int R = maze.length, C = maze[0].length;
    if (maze[0][0] == 0 || maze[R - 1][C - 1] == 0) return false;
    return dfs(maze, 0, 0, R, C);
}

private boolean dfs(int[][] maze, int r, int c, int R, int C) {
    if (r >= R || c >= C || maze[r][c] == 0) return false;
    if (r == R - 1 && c == C - 1) return true;
    return dfs(maze, r, c + 1, R, C) || dfs(maze, r + 1, c, R, C);
}

