def hasPathDownRight(self, maze: list[list[int]]) -> bool:
    R, C = len(maze), len(maze[0])
    if maze[0][0] == 0 or maze[R - 1][C - 1] == 0:
        return False

    def dfs(r: int, c: int) -> bool:
        if r >= R or c >= C or maze[r][c] == 0:
            return False
        if r == R - 1 and c == C - 1:
            return True
        return dfs(r, c + 1) or dfs(r + 1, c)

    return dfs(0, 0)

