code.java:
private static final int[] DR = {1, 0, 0, -1}; // D, L, R, U
private static final int[] DC = {0, -1, 1, 0};

public boolean hasPath(int[][] maze) {
    int R = maze.length, C = maze[0].length;
    if (maze[0][0] == 0 || maze[R - 1][C - 1] == 0) return false;
    boolean[][] visited = new boolean[R][C];
    return solve(maze, 0, 0, R, C, visited);
}

private boolean solve(int[][] maze, int r, int c, int R, int C, boolean[][] visited) {
    if (r < 0 || r >= R || c < 0 || c >= C) return false; // off grid
    if (maze[r][c] == 0 || visited[r][c]) return false;    // wall or on path
    if (r == R - 1 && c == C - 1) return true;             // goal
    visited[r][c] = true;                                  // choose
    for (int d = 0; d < 4; d++) {
        if (solve(maze, r + DR[d], c + DC[d], R, C, visited)) {
            return true;                                   // one path found
        }
    }
    visited[r][c] = false;                                 // un-choose (backtrack)
    return false;
}

code.python:
DR = (1, 0, 0, -1)  # D, L, R, U
DC = (0, -1, 1, 0)

def hasPath(self, maze: list[list[int]]) -> bool:
    R, C = len(maze), len(maze[0])
    if maze[0][0] == 0 or maze[R - 1][C - 1] == 0:
        return False
    visited = [[False] * C for _ in range(R)]

    def solve(r: int, c: int) -> bool:
        if r < 0 or r >= R or c < 0 or c >= C:
            return False                       # off grid
        if maze[r][c] == 0 or visited[r][c]:
            return False                       # wall or on path
        if r == R - 1 and c == C - 1:
            return True                        # goal
        visited[r][c] = True                   # choose
        for dr, dc in zip(DR, DC):
            if solve(r + dr, c + dc):
                return True                    # one path found
        visited[r][c] = False                  # un-choose (backtrack)
        return False

    return solve(0, 0)

